        <?php if(!$assets): ?><div class="bm-project-document-empty">No installed assets registered yet.</div><?php else: ?><div class="bm-asset-list"><?php foreach($assets as $asset): ?><article class="bm-asset-row"><div><strong><?= $esc($asset->asset_tag); ?></strong><small><?= $esc($asset->item_name ?: $asset->model); ?><?= $asset->serial_number?' · SN '.$esc($asset->serial_number):''; ?></small></div><span>Warranty to <?= $esc($asset->warranty_end ?: 'none'); ?><small><?= $esc($asset->equipment_status ?: $asset->status); ?></small></span><?php if(get_instance()->permissions('service_jobs_edit')): ?><form method="post" action="<?= base_url('building_projects/schedule_maintenance/'.(int)$project->job_id.'/'.(int)$asset->id); ?>"><input type="hidden" name="<?= $csrfName; ?>" value="<?= $csrfHash; ?>"><input type="hidden" name="request_key" value="<?= bin2hex(random_bytes(20)); ?>"><input type="date" name="due_date" value="<?= date('Y-m-d',strtotime('+12 months')); ?>" required><input type="number" name="interval_months" min="1" max="120" value="12"><button class="bo-button compact" type="submit">Schedule service</button></form><?php endif; ?></article><?php endforeach; ?></div><?php endif; ?>
        <?php if($maintenancePlans): ?><div class="bm-maintenance-list"><h3>Maintenance schedule</h3><?php foreach($maintenancePlans as $plan): ?><div><strong><?= $esc($plan->asset_tag); ?></strong><span><?= $esc($plan->due_date); ?> · every <?= (int)$plan->interval_months; ?> months · <?= $esc($plan->status); ?></span></div><?php endforeach; ?></div><?php endif; ?>
        <?php if($assets && get_instance()->permissions('service_jobs_edit')): ?><form class="bm-claim-form" method="post" action="<?= base_url('building_projects/create_warranty_claim/'.(int)$project->job_id); ?>"><input type="hidden" name="<?= $csrfName; ?>" value="<?= $csrfHash; ?>"><input type="hidden" name="request_key" value="<?= bin2hex(random_bytes(20)); ?>"><select name="asset_id" data-bm-select required><option value="">Asset</option><?php foreach($assets as $asset): ?><option value="<?= (int)$asset->id; ?>"><?= $esc($asset->asset_tag); ?></option><?php endforeach; ?></select><input name="claim_reference" maxlength="120" placeholder="WARRANTY-001" required><input name="issue" maxlength="8000" placeholder="Describe the issue" required><button class="bo-button compact" type="submit">Open warranty claim</button></form><?php endif; ?>
        <?php if($warrantyClaims): ?><div class="bm-claims-list"><h3>Warranty claims</h3><?php foreach($warrantyClaims as $claim): ?><div><span><strong><?= $esc($claim->claim_reference); ?></strong><small><?= $esc($claim->asset_tag); ?> · <?= $esc($claim->issue); ?></small></span><?php if(get_instance()->permissions('service_jobs_edit') && $claim->status!=='resolved'): ?><form method="post" action="<?= base_url('building_projects/resolve_warranty_claim/'.(int)$project->job_id.'/'.(int)$claim->id); ?>"><input type="hidden" name="<?= $csrfName; ?>" value="<?= $csrfHash; ?>"><input type="hidden" name="status" value="resolved"><input name="resolution" maxlength="8000" placeholder="Resolution" required><button class="bo-button compact" type="submit">Resolve</button></form><?php else: ?><span class="bm-material-po"><?= $esc($claim->status); ?></span><?php endif; ?></div><?php endforeach; ?></div><?php endif; ?>
      </section>
      <?php if ($building_project_tasks): ?><section class="bm-project-info-card"><div class="bm-project-section-head"><div><span class="bm-projects-eyebrow">Field execution</span><h2>Team task cards</h2></div><span class="bm-project-muted"><?= count($building_project_tasks); ?> tasks</span></div><div class="bm-project-tasks"><?php foreach($building_project_tasks as $task): ?><div><span class="bm-task-state <?= $esc($task->status); ?>"></span><span><strong><?= $esc($task->title); ?></strong><small><?= $esc($task->assignee ?: 'Unassigned'); ?><?= $task->due_date ? ' · due '.$esc($task->due_date) : ''; ?></small></span></div><?php endforeach; ?></div></section><?php endif; ?>
    </div>
    <aside class="bm-project-detail-side"><section class="bm-project-info-card"><div class="bm-project-section-head"><div><span class="bm-projects-eyebrow">Audit trail</span><h2>What happened</h2></div></div><div class="bm-project-events"><?php if ($building_project_events): foreach($building_project_events as $event): ?><article><span class="bm-event-dot"></span><div><small><?= $esc($event->created_at); ?></small><strong><?= $esc($stages[$event->to_stage] ?? ucfirst((string)$event->to_stage)); ?></strong><p><?= $esc($event->note ?: 'Stage updated.'); ?></p></div></article><?php endforeach; else: ?><div class="bm-project-document-empty">Project history will appear here as surveys, approvals, dispatch and installation updates are recorded.</div><?php endif; ?></div></section></aside>
  </div>
</div>
